/* GENERATED by web_app/build/build_site.py from dashboard/static/campus.js -- edit the dashboard, not this copy */
"use strict";

// The Campus tab: a replay of what NetLogo's visual mode would have shown for the
// loaded run -- recorded by the view trace while the run was made (abm_view.txt).
//
// Drawn the way the NetLogo interface draws it: the basemap, buildings as houses,
// a sample of people (residents green, commuters red, faculty blue), manholes and
// pipes coloured by flow with NetLogo's own thresholds, and cyan flow packets.
// Building colours use the occupancy scheme in the model's (commented-out)
// update-building-appearance.  People glide between buildings between ticks, as
// NetLogo's own cosmetic animation does; nothing here changes what the model did.

const CV = {
  runId: null, data: null, loading: null, img: null,
  t: 0, playing: false, last: null, speed: 4, raf: null,
  chart: null, hover: null, lastSync: 0, follow: null,
};
const CLASS_COLOR = { R: "#2e9e44", C: "#d7301f", F: "#2a62c9" };
const CLASS_NAME = { R: "residents", C: "commuters", F: "faculty" };
// NetLogo's own off-campus spots: commuters (-15, 0), faculty (10, -8), plus up to 3 patches
const OFF = { C: [-15, 0], F: [10, -8] };
// Node and pipe colours by flow, gal per 15-min tick (update-network-appearance)
const flowColor = (q) => (q > 50 ? "#a35bd6" : q > 20 ? "#f28e2b" : q > 0 ? "#7fdc3a" : "#ffffff");
// Building occupancy, as the model's update-building-appearance would colour it
const occColor = (r) => (r <= 0 ? "#9aa0a6" : r <= 0.25 ? "#3b6fd8" : r <= 0.5 ? "#21b5c9"
  : r <= 0.75 ? "#f2c12e" : "#e0453a");
const cq = (s) => document.querySelector(s);

function campusWire() {
  document.querySelector('.tab[data-tab="campus"]').addEventListener("click", campusShow);
  cq("#cv-play").addEventListener("click", () => (CV.playing ? cvPause() : cvPlay()));
  cq("#cv-time").addEventListener("input", (e) => { cvPause(); CV.t = Number(e.target.value); cvFrame(true); });
  cq("#cv-speed").addEventListener("change", (e) => { CV.speed = Number(e.target.value); });
  ["#cv-people", "#cv-packets", "#cv-labels"].forEach(s => cq(s).addEventListener("change", () => cvFrame(true)));
  cq("#cv-record").addEventListener("click", cvRecord);
  cq("#cv-desktop").addEventListener("click", cvDesktop);
  const cv = cq("#cv-canvas");
  cv.addEventListener("pointermove", cvHover);
  cv.addEventListener("pointerleave", () => { CV.hover = null; cq("#cv-tip").hidden = true; });
  new ResizeObserver(() => { if (CV.data) cvFrame(true); }).observe(cq("#cv-stage"));
  CV.img = new Image();
  CV.img.onload = () => { if (CV.data) cvFrame(true); };
  CV.img.src = "basemap.png";
}

// Called by loadRun; the replay itself is fetched only when the tab is opened.
function campusLoad(runId) {
  if (CV.runId === runId && (CV.data || CV.loading)) return;
  cvPause();
  CV.runId = runId; CV.data = null; CV.loading = null;
  cq("#cv-run").textContent = runId;
  cq("#cv-controls").hidden = false;
  cq("#cv-body").hidden = true;
  cq("#cv-record").hidden = true;
  cq("#cv-note").textContent = "";
  if (cq("#tab-campus").classList.contains("active")) campusShow();
}

async function campusShow() {
  if (!CV.runId) {
    cq("#cv-note").textContent = "Run the simulation to watch the agents here.";
    cq("#cv-controls").hidden = true;
    return;
  }
  if (CV.data || CV.loading) { if (CV.data) cvFrame(true); return; }
  const run = CV.runId;
  cq("#cv-note").textContent = `Loading the campus view of ${run}…`;
  cq("#cv-note").classList.add("loading");
  CV.loading = fetch(`/api/runs/${encodeURIComponent(run)}/view`);
  let r;
  try { r = await CV.loading; } catch (e) { r = null; }
  cq("#cv-note").classList.remove("loading");
  if (CV.runId !== run) return;
  CV.loading = null;
  if (!r || !r.ok) {
    let msg = r ? await r.text() : "the dashboard did not answer";
    try { msg = JSON.parse(msg).detail || msg; } catch (e) { /* text */ }
    if (r && r.status === 404 && msg === "not recorded") {
      cq("#cv-note").textContent = "This run was made without recording the campus view. Record it now: "
        + "the ABM is re-run at the same seed and settings (about a minute), and the recording is kept only "
        + "if the re-run reproduces this run's output exactly.";
      cq("#cv-record").hidden = false;
    } else {
      cq("#cv-note").textContent = msg;
    }
    return;
  }
  CV.data = prepare(await r.json());
  if (CV.runId !== run) return;
  cq("#cv-note").textContent = "";
  cq("#cv-body").hidden = false;
  const n = CV.data.ticks.length;
  cq("#cv-time").max = n - 1;
  CV.t = Math.min(CV.t, n - 1) || Math.min(n - 1, CV.data.warmup_ticks + 7 * 4);   // a Monday 07:00 after warm-up
  cvChart();
  cvFrame(true);
}

// Precompute positions: each person keeps a fixed small offset so a building's crowd
// reads as a cluster rather than one dot.
function prepare(d) {
  d.bpos = Object.fromEntries(d.buildings.map(b => [b.id, [b.x, b.y]]));
  d.npos = Object.fromEntries(d.nodes.map(n => [n.id, n]));
  d.jitter = d.classes.map((_, i) => {
    const a = ((i * 2654435761) % 1000) / 1000 * Math.PI * 2;
    const r = 0.4 + ((i * 40503) % 1000) / 1000 * 1.4;
    return [Math.cos(a) * r, Math.sin(a) * r];
  });
  d.offJ = d.classes.map((_, i) => [((i * 7919) % 300) / 100, ((i * 104729) % 300) / 100]);
  d.flowIdx = d.flow ? Object.fromEntries(d.flow.ids.map((id, i) => [id, i])) : {};
  d.last = d.classes.map(() => null);
  return d;
}

function personPos(d, i, b) {
  const cls = d.classes[i];
  if (b > 0 && d.bpos[b]) {
    const [x, y] = d.bpos[b];
    return [x + d.jitter[i][0], y + d.jitter[i][1]];
  }
  if (OFF[cls] && !(window.cvHideOffCampus && window.cvHideOffCampus())) return [OFF[cls][0] + d.offJ[i][0], OFF[cls][1] + d.offJ[i][1]];
  return null;                               // a resident in no building: not drawn
}

// --------------------------------------------------------------- drawing

function cvFrame(force) {
  const d = CV.data;
  if (!d) return;
  const n = d.ticks.length;
  const ti = Math.max(0, Math.min(n - 1, Math.floor(CV.t)));
  const frac = Math.min(1, (CV.t - ti) * 2.5);           // NetLogo moves people in a few frames
  const stage = cq("#cv-stage"), canvas = cq("#cv-canvas");
  const size = Math.max(320, Math.min(stage.clientWidth, 760));
  const dpr = window.devicePixelRatio || 1;
  if (canvas.width !== Math.round(size * dpr)) {
    canvas.width = Math.round(size * dpr); canvas.height = Math.round(size * dpr);
    canvas.style.width = size + "px"; canvas.style.height = size + "px";
  }
  const g = canvas.getContext("2d");
  g.setTransform(dpr, 0, 0, dpr, 0, 0);
  const W = d.world, span = (W.x1 - W.x0 + 1);
  const X = (x) => (x - (W.x0 - 0.5)) / span * size;
  const Y = (y) => size - (y - (W.y0 - 0.5)) / span * size;
  CV.geo = { X, Y, size };

  g.fillStyle = "#000"; g.fillRect(0, 0, size, size);
  if (!(window.cvBackground && window.cvBackground(g, X, Y, size, dpr, ti))) {
  if (CV.img && CV.img.complete && CV.img.naturalWidth) g.drawImage(CV.img, 0, 0, size, size);
  g.fillStyle = "rgba(0,0,0,0.28)"; g.fillRect(0, 0, size, size);
  }

  const flow = d.flow ? d.flow.values[ti] : null;
  const q = (id) => (flow && d.flowIdx[id] != null ? flow[d.flowIdx[id]] : 0);

  // pipes, coloured by the flow leaving their upstream node
  g.lineWidth = 2;
  d.pipes.forEach(([a, b]) => {
    const A = d.npos[a], B = d.npos[b];
    if (!A || !B) return;
    g.strokeStyle = flowColor(q(a));
    g.beginPath(); g.moveTo(X(A.x), Y(A.y)); g.lineTo(X(B.x), Y(B.y)); g.stroke();
  });
  // flow packets (cosmetic, like NetLogo's): up to 4 per flowing pipe
  if (cq("#cv-packets").checked) {
    g.fillStyle = "#4fe3f0";
    const phase = performance.now() / 1400;
    d.pipes.forEach(([a, b], k) => {
      const qa = q(a); if (!(qa > 0)) return;
      const A = d.npos[a], B = d.npos[b]; if (!A || !B) return;
      const m = Math.min(4, Math.max(1, Math.round(qa / 10)));
      for (let j = 0; j < m; j++) {
        const p = (phase + j / m + (k * 0.137) % 1) % 1;
        g.beginPath();
        g.arc(X(A.x + p * (B.x - A.x)), Y(A.y + p * (B.y - A.y)), 1.6, 0, Math.PI * 2);
        g.fill();
      }
    });
  }
  // nodes
  d.nodes.forEach(nd => {
    g.fillStyle = flowColor(q(nd.id));
    g.beginPath(); g.arc(X(nd.x), Y(nd.y), nd.gauge ? 5 : 3, 0, Math.PI * 2); g.fill();
    if (nd.gauge) {
      g.strokeStyle = "#ff3b3b"; g.lineWidth = 2; g.stroke();
      g.fillStyle = "#fff"; g.font = "11px system-ui"; g.fillText(nodeLabel(nd.name), X(nd.x) + 8, Y(nd.y) + 4);
    } else if (cq("#cv-labels").checked && q(nd.id) > 0) {
      g.fillStyle = "#fff"; g.font = "9px system-ui"; g.fillText(q(nd.id).toFixed(1), X(nd.x) + 5, Y(nd.y) - 4);
    }
  });
  // buildings: a house, coloured by occupancy / capacity
  const occ = d.occ[ti];
  d.buildings.forEach((b, i) => {
    const r = b.cap > 0 ? occ[i] / b.cap : 0;
    if (!(window.cvBuilding && window.cvBuilding(b))) house(g, X(b.x), Y(b.y), 7, occColor(r));
  });
  // people
  if (cq("#cv-people").checked) {
    const now = d.loc[ti], prev = ti > 0 ? d.loc[ti - 1] : (d.init ? d.init[1] : now);
    for (let i = 0; i < d.classes.length; i++) {
      const p1 = personPos(d, i, now[i]);
      if (!p1) continue;
      const p0 = personPos(d, i, prev[i]) || p1;
      const x = p0[0] + (p1[0] - p0[0]) * frac, y = p0[1] + (p1[1] - p0[1]) * frac;
      g.fillStyle = CLASS_COLOR[d.classes[i]] || "#fff";
      g.beginPath(); g.arc(X(x), Y(y), 2.4, 0, Math.PI * 2); g.fill();
    }
  }

  if (force || ti !== CV.lastTick) {
    CV.lastTick = ti;
    cq("#cv-time").value = ti;
    const ms = d.start_ms + ti * d.step_ms;
    cq("#cv-time-label").textContent = fmtTime(ms) + (ti < d.warmup_ticks ? " · warm-up" : "")
      + `  ·  tick ${ti}`;
    cvReadout(ti);
    if (CV.chart) CV.chart.setMarker(ms);
    if (window.cvOnTick) window.cvOnTick(ms);
    cvSyncMap(ms, force);
  }
  if (CV.hover) cvShowTip();
}

function house(g, x, y, s, fill) {
  g.beginPath();
  g.moveTo(x, y - s); g.lineTo(x + s, y - s * 0.1); g.lineTo(x + s * 0.75, y - s * 0.1);
  g.lineTo(x + s * 0.75, y + s * 0.8); g.lineTo(x - s * 0.75, y + s * 0.8);
  g.lineTo(x - s * 0.75, y - s * 0.1); g.lineTo(x - s, y - s * 0.1); g.closePath();
  g.fillStyle = fill; g.fill();
  g.strokeStyle = "rgba(0,0,0,.65)"; g.lineWidth = 1; g.stroke();
}

function cvReadout(ti) {
  const d = CV.data;
  const loc = d.loc[ti];
  const on = { R: 0, C: 0, F: 0 }, tot = { R: 0, C: 0, F: 0 };
  d.classes.forEach((c, i) => { tot[c]++; if (loc[i] > 0) on[c]++; });
  const host = cq("#cv-readout");
  host.innerHTML = "";
  const row = (k, v, color) => {
    const r = document.createElement("div"); r.className = "cv-row";
    const a = document.createElement("span");
    if (color) { const i = document.createElement("i"); i.style.background = color; a.append(i); }
    a.append(document.createTextNode(k));
    const b = document.createElement("b"); b.textContent = v;
    r.append(a, b); host.append(r);
  };
  row("people in buildings", d.occ[ti].reduce((a, b) => a + b, 0).toLocaleString());
  if (d.water) row("water this 15 min", Math.round(d.water[ti].reduce((a, b) => a + b, 0)).toLocaleString() + " gal");
  const head = document.createElement("div"); head.className = "cv-sub";
  head.textContent = `sample shown (${d.classes.length} people), on campus:`;
  host.append(head);
  ["R", "C", "F"].forEach(c => row(CLASS_NAME[c], `${on[c]} of ${tot[c]}`, CLASS_COLOR[c]));
}

function cvChart() {
  if (window.cvNoStationChart) return;
  const d = CV.data;
  if (!d.flow) { cq("#cv-chart-card").hidden = true; return; }
  cq("#cv-chart-card").hidden = false;
  if (!CV.chart) CV.chart = LineChart(cq("#cv-chart"));
  const t = d.flow.values.map((_, i) => d.start_ms + i * d.step_ms);
  const gaugeColor = { "Waste-1": "#d62728", "Waste-2": "#1f77b4", "Waste-3": "#2ca02c" };   // NetLogo's pens
  const series = d.nodes.filter(n => n.gauge).sort((a, b) => nodeLabel(a.name).localeCompare(nodeLabel(b.name))).map(n => ({
    name: nodeLabel(n.name), color: gaugeColor[n.gauge] || "#555",
    values: d.flow.values.map(row => row[d.flowIdx[n.id]]),
  }));
  CV.chart.update({ t, series, unit: "gal/15 min", label: "ABM node flow",
                    warmupEnd: d.start_ms + d.warmup_ticks * d.step_ms });
}

// Keep the Map tab on the same moment when it shows the same run.
function cvSyncMap(ms, force) {
  if (typeof MAP === "undefined" || MAP.runId !== CV.runId || !MAP.times) return;
  const now = performance.now();
  if (!force && now - CV.lastSync < 800) return;
  CV.lastSync = now;
  let best = 0;
  for (let i = 0; i < MAP.times.length; i++) if (Math.abs(MAP.times[i] - ms) < Math.abs(MAP.times[best] - ms)) best = i;
  setTime(best);
}

// ------------------------------------------------------------ playback

function cvPlay() {
  if (!CV.data) return;
  if (CV.t >= CV.data.ticks.length - 1) CV.t = 0;
  CV.playing = true; CV.last = null;
  cq("#cv-play").textContent = "❚❚"; cq("#cv-play").title = "pause";
  const step = (ts) => {
    if (!CV.playing) return;
    if (CV.last != null) CV.t += (ts - CV.last) / 1000 * CV.speed;
    CV.last = ts;
    if (CV.t >= CV.data.ticks.length - 1) { CV.t = CV.data.ticks.length - 1; cvFrame(true); cvPause(); return; }
    cvFrame(false);
    CV.raf = requestAnimationFrame(step);
  };
  CV.raf = requestAnimationFrame(step);
}

function cvPause() {
  CV.playing = false;
  if (CV.raf) cancelAnimationFrame(CV.raf);
  CV.raf = null;
  const b = cq("#cv-play"); if (b) { b.textContent = "▶"; b.title = "play"; }
  // the Map tab is only synced now and then while playing; land it on the paused moment
  if (CV.data) {
    const ti = Math.max(0, Math.min(CV.data.ticks.length - 1, Math.floor(CV.t)));
    cvSyncMap(CV.data.start_ms + ti * CV.data.step_ms, true);
  }
}

// --------------------------------------------------------------- hover

function cvHover(ev) {
  if (!CV.data || !CV.geo) return;
  const r = cq("#cv-canvas").getBoundingClientRect();
  CV.hover = { x: ev.clientX - r.left, y: ev.clientY - r.top };
  cvShowTip();
}

function cvShowTip() {
  const d = CV.data, { X, Y } = CV.geo, h = CV.hover, tip = cq("#cv-tip");
  const ti = Math.max(0, Math.min(d.ticks.length - 1, Math.floor(CV.t)));
  let best = null, bd = 12;
  d.buildings.forEach((b, i) => {
    const dist = Math.hypot(X(b.x) - h.x, Y(b.y) - h.y);
    if (dist < bd) { bd = dist; best = ["b", b, i]; }
  });
  d.nodes.forEach(nd => {
    const dist = Math.hypot(X(nd.x) - h.x, Y(nd.y) - h.y);
    if (dist < Math.min(bd, 8)) { bd = dist; best = ["n", nd]; }
  });
  if (!best) { tip.hidden = true; return; }
  tip.innerHTML = "";
  const line = (txt, strong) => { const e = document.createElement(strong ? "b" : "div"); e.textContent = txt; tip.append(e); };
  if (best[0] === "b") {
    const [, b, i] = best;
    line(b.name || `building ${b.id}`, true);
    line(`${b.cls} · drains to node ${b.drain}`);
    line(`${d.occ[ti][i]} of ${b.cap} people`);
    if (d.water) line(`${d.water[ti][i].toFixed(1)} gal this 15 min`);
  } else {
    const nd = best[1];
    const qv = d.flow && d.flowIdx[nd.id] != null ? d.flow.values[ti][d.flowIdx[nd.id]] : null;
    line(nd.gauge ? `${nodeLabel(nd.name)} (${nd.name})` : nd.name, true);
    line(qv != null ? `${qv.toFixed(1)} gal this 15 min (routed, ABM)` : "no flow recorded");
  }
  tip.hidden = false;
  tip.style.left = Math.min(h.x + 14, CV.geo.size - 190) + "px";
  tip.style.top = (h.y + 12) + "px";
}

// --------------------------------------------- record afterwards / NetLogo

async function cvRecord() {
  const run = CV.runId;
  const btn = cq("#cv-record");
  btn.disabled = true;
  let job;
  try {
    const r = await fetch(`/api/runs/${encodeURIComponent(run)}/view`, { method: "POST" });
    job = await r.json();
    if (!r.ok) throw new Error(job.detail || r.statusText);
  } catch (e) { cq("#cv-note").textContent = "Could not start: " + e.message; btn.disabled = false; return; }
  cq("#cv-note").textContent = "Recording: re-running the ABM…";
  cq("#cv-note").classList.add("loading");
  const src = new EventSource(`/api/runs/${encodeURIComponent(job.id)}/events`);
  src.onmessage = (ev) => {
    const s = JSON.parse(ev.data);
    const last = s.log.length ? s.log[s.log.length - 1] : "";
    cq("#cv-note").textContent = `Recording (${s.stage || s.status}, ${s.percent}%): ${last}`;
    if (s.status === "done" || s.status === "failed") {
      src.close();
      cq("#cv-note").classList.remove("loading");
      btn.disabled = false;
      if (s.status === "failed") { cq("#cv-note").textContent = "Not recorded: " + (s.error || "failed"); return; }
      cq("#cv-record").hidden = true;
      CV.data = null;
      if (CV.runId === run) campusShow();
    }
  };
  src.onerror = () => { src.close(); btn.disabled = false; cq("#cv-note").classList.remove("loading"); };
}

async function cvDesktop() {
  const run = CV.runId;
  if (!run) return;
  const msg = cq("#cv-desktop-msg");
  msg.textContent = "Opening NetLogo…";
  try {
    const r = await fetch(`/api/runs/${encodeURIComponent(run)}/desktop`, { method: "POST" });
    const info = await r.json();
    if (!r.ok) throw new Error(info.detail || r.statusText);
    msg.textContent = `NetLogo is opening ${info.path} (it can take ~20 s). Press "Set up" (it runs seed ${info.seed} `
      + `for ${info.days} days), then "go". It is NetLogo's own run, at its own speed; groundwater and SWMM are not in it.`
      + (info.note ? " Note: " + info.note : "");
  } catch (e) { msg.textContent = "Could not open NetLogo: " + e.message; }
}

window.campusWire = campusWire;
window.campusLoad = campusLoad;
